page_data_script:
def clean(value):
    return frappe.utils.escape_html(value or "")


def day_month_year(value):
    text = str(value)
    months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    return months[int(text[5:7]) - 1] + " " + str(int(text[8:10])) + ", " + text[:4]


def plain_text(html):
    text = frappe.utils.strip_html(html or "")
    for entity, char in (("&nbsp;", " "), ("&lt;", "<"), ("&gt;", ">"), ("&quot;", '"'), ("&#39;", "'"), ("&amp;", "&")):
        text = text.replace(entity, char)
    return text.strip()


def safe_url(value):
    value = value or ""
    return frappe.utils.escape_html(value) if value.startswith(("/", "https://", "http://")) else ""


def path_segment(value):
    for char, code in (("%", "%25"), ("/", "%2F"), ("?", "%3F"), ("#", "%23"), ("\\", "%5C"), (" ", "%20")):
        value = value.replace(char, code)
    return value


def first_image(html):
    html = html or ""
    start = html.find("<img")
    if start == -1:
        return ""
    src_start = html.find('src="', start)
    if src_start == -1:
        return ""
    src_start += 5
    src_end = html.find('"', src_start)
    if src_end == -1:
        return ""
    return html[src_start:src_end].replace("&amp;", "&")


handle = frappe.form_dict.handle or ""

if frappe.session.user == "Guest":
    redirect("/login?redirect=/publications/" + path_segment(handle) + "/members")

data.w = {"id": clean(handle)}
